def quicksort(arr, depth=0):
    if len(arr) <= 1:
        return arr
    pivot = arr[0]
    left  = [x for x in arr[1:] if x <= pivot]
    right = [x for x in arr[1:] if x > pivot]
    print('  ' * depth + f'피벗 {pivot}: {left} | {right}')
    return quicksort(left, depth + 1) + [pivot] + quicksort(right, depth + 1)

print('결과:', quicksort([5, 3, 8, 1, 7, 2, 6, 4]))
